CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) AND (_user_id=auth.uid() OR auth.role()='service_role') $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE TABLE public.customer_support_notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE, author_id uuid NOT NULL, body text NOT NULL CHECK(length(body) BETWEEN 1 AND 4000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.customer_support_notes TO authenticated;
GRANT ALL ON public.customer_support_notes TO service_role;
ALTER TABLE public.customer_support_notes ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_read ON public.customer_support_notes FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY staff_write ON public.customer_support_notes FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin') AND author_id=auth.uid());
CREATE TABLE public.push_devices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE, token text NOT NULL UNIQUE, label text NOT NULL DEFAULT 'This device', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.push_devices TO authenticated;
GRANT ALL ON public.push_devices TO service_role;
ALTER TABLE public.push_devices ENABLE ROW LEVEL SECURITY;
CREATE POLICY device_owner ON public.push_devices TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.push_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), device_id uuid NOT NULL REFERENCES public.push_devices(id) ON DELETE CASCADE, alert_id uuid NOT NULL REFERENCES public.strategy_alerts(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sending','sent','failed')), attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, lease_token uuid, sent_at timestamptz, error_code text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(device_id,alert_id));
GRANT ALL ON public.push_deliveries TO service_role;
ALTER TABLE public.push_deliveries ENABLE ROW LEVEL SECURITY;
CREATE INDEX push_due ON public.push_deliveries(available_at) WHERE status IN ('pending','sending');
CREATE FUNCTION public.enqueue_strategy_push() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.push_deliveries(device_id,alert_id) SELECT id,NEW.id FROM public.push_devices WHERE user_id=NEW.user_id AND created_at<=NEW.created_at ON CONFLICT DO NOTHING; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.enqueue_strategy_push() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER strategy_push_queue AFTER INSERT ON public.strategy_alerts FOR EACH ROW EXECUTE FUNCTION public.enqueue_strategy_push();
CREATE FUNCTION public.claim_push_deliveries(p_token uuid) RETURNS SETOF public.push_deliveries LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN QUERY WITH due AS (SELECT id FROM public.push_deliveries WHERE (status='pending' OR (status='sending' AND lease_until<now())) AND available_at<=now() AND attempts<5 ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 20) UPDATE public.push_deliveries d SET status='sending', attempts=d.attempts+1,lease_until=now()+interval '60 seconds',lease_token=p_token FROM due WHERE d.id=due.id RETURNING d.*; END $$;
REVOKE ALL ON FUNCTION public.claim_push_deliveries(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_push_deliveries(uuid) TO service_role;